template <typename F>
void dispatch_stride(bool k_major, int m, int k, F&& f) {
  if (k_major) {
    f(make_stride(k, Int<1>{}, m * k), std::true_type{});
  } else {
    f(make_stride(Int<1>{}, m, m * k), std::false_type{});
  }
}

